PUBLIC_FILES={'summary.json','report.html'}
HEX=re.compile(r'[0-9a-f]{64}')
STAGES=frozenset({'initializing','payload_verified','toolchains','pinned_inputs','forced_dispatch',
 'activation_sources','affine_sources','operator_gate','link_original','link_rebuilt','link_candidate',
 'link_diagnostic_candidate','prepared','attribution_sources','attribution_link_original',
 'attribution_link_candidate','attribution_prepared','browser_install','profile_sessions','counter_sessions','complete','failed'})
LINK_DISK_MINIMUM=4*1024**3
BUILD_DISK_MINIMUM=1024**3
ERRORS={'ValueError','RuntimeError','PermissionError','FileNotFoundError','OSError','CalledProcessError','TimeoutExpired','KeyboardInterrupt','OtherError'}


def need(value,message):
    if not value:raise ValueError(message)


def digest(data):return hashlib.sha256(data).hexdigest()


def same(value,expected):
    if type(value) is not type(expected):return False
    if isinstance(value,dict):return value.keys()==expected.keys() and all(same(value[k],expected[k]) for k in value)
    if isinstance(value,(list,tuple)):return len(value)==len(expected) and all(same(a,b) for a,b in zip(value,expected))
    return value==expected


def no_duplicates(pairs):
    value={}
    for key,item in pairs:
        need(key not in value,'Duplicate JSON key');value[key]=item
    return value


def decode_json(data):
    def no_constant(_):raise ValueError('Nonfinite JSON')
    return json.loads(data,object_pairs_hook=no_duplicates,parse_constant=no_constant)


def load_payload():
    need(len(PAYLOAD_B85)<=4_000_000,'Compressed payload bound')
    compressed=base64.b85decode(PAYLOAD_B85);need(digest(compressed)==PAYLOAD_SHA256,'Embedded payload hash mismatch')
    decoder=zlib.decompressobj();data=decoder.decompress(compressed,8_000_001)
    need(len(data)<=8_000_000 and decoder.eof and not decoder.unconsumed_tail and not decoder.unused_data,'Payload expansion bound')
    rows=decode_json(data);need(type(rows) is dict and 20<=len(rows)<=96,'Payload member count')
    result={}
    for name,row in rows.items():
        need(type(name) is str and re.fullmatch(r'[A-Za-z0-9_./-]{1,200}',name),'Unsafe embedded path')
        p=PurePosixPath(name)
        need(not p.is_absolute() and str(p)==name and all(x not in ('','.','..') for x in p.parts),'Unsafe embedded path')
        need(type(row) is dict and set(row)=={'sha256','base64'} and type(row['sha256']) is str and HEX.fullmatch(row['sha256']),'Payload record schema')
        value=base64.b64decode(row['base64'],validate=True)
        need(len(value)<=1_000_000 and digest(value)==row['sha256'],'Embedded member mismatch')
        need(p.suffix in {'.py','.js','.json','.c','.patch'},'Source-only member type');result[name]=value
    return result


def checked_path(path):
    path=Path(path).expanduser().absolute()
    for item in [path,*path.parents]:need(not item.is_symlink(),'Refuse symlink path')
    return path.resolve()


def extract_payload(folder):
    folder=checked_path(folder);folder.mkdir(parents=True,exist_ok=True,mode=0o700)
    for name,data in load_payload().items():
        target=checked_path(folder/name);need(target.is_relative_to(folder),'Helper path escape')
        target.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
        if target.exists():need(target.is_file() and target.read_bytes()==data,'Cached embedded source modified')
        else:
            with target.open('xb') as stream:stream.write(data)
    return folder


@functools.lru_cache(maxsize=24)
def import_helper(folder,name):
    folder=Path(folder);sys.path.insert(0,str(folder))
    spec=importlib.util.spec_from_file_location('_off_embedded_'+name,folder/(name+'.py'))
    module=importlib.util.module_from_spec(spec);sys.modules[spec.name]=module;spec.loader.exec_module(module)
    return module


def receipt_tools(payload):
    m=import_helper(payload,'baseline_receipts');m.PAYLOAD_SHA256=PAYLOAD_SHA256;m.load_payload=load_payload
    m.digest=digest;m.Path=Path;m.__file__=__file__;return m


def atomic_json(path,value):
    path=checked_path(path);temporary=checked_path(path.with_suffix(path.suffix+'.tmp'))
    raw=(json.dumps(value,sort_keys=True,indent=2,allow_nan=False)+'\n').encode()
    with temporary.open('wb') as stream:stream.write(raw)
    temporary.replace(path)


def minimal_report(status,stage,exception_class=None):
    result=dict(schema=SCHEMA,status=status,stage=stage,distribution_sha256=digest(Path(__file__).read_bytes()),
        payload_sha256=PAYLOAD_SHA256,diagnostic_valid=False,primary_speed_claim=False,inference_calls=None,cpu_time_series_measured=False)
    if exception_class is not None:result['exception_class']=exception_class
    return result


def minimal_validate(report):
    fields={'schema','status','stage','distribution_sha256','payload_sha256','diagnostic_valid','primary_speed_claim','inference_calls','cpu_time_series_measured'}
    need(type(report) is dict and set(report) in (fields,fields|{'exception_class'}),'Failure report schema')
    need(report['schema']==SCHEMA and report['status']=='failed' and report['stage'] in STAGES,'Failure status')
    need(report['diagnostic_valid'] is False and report['primary_speed_claim'] is False and report['cpu_time_series_measured'] is False and report['inference_calls'] is None,'Failure measurement claim')
    need(report['distribution_sha256']==digest(Path(__file__).read_bytes()) and report['payload_sha256']==PAYLOAD_SHA256,'Failure provenance')
    if 'exception_class' in report:need(report['exception_class'] in ERRORS,'Failure class allowlist')


def production_receipt(payload,manifest,operator):
    full=receipt_tools(payload).make_envelope(manifest,{'status':'complete' if operator else 'prepare_only'},operator)
    return {k:full[k] for k in ('source_refs','toolchain_provisioning','artifacts','source_proof','operator_probe')}


def validate_production(payload,value,required=False):
    need(type(value) is dict and set(value)=={'source_refs','toolchain_provisioning','artifacts','source_proof','operator_probe'},'Production receipt schema')
    operator=value['operator_probe'];need(type(operator) is dict,'Operator receipt type')
    status='complete' if operator.get('executed') is True else 'prepare_only'
    full=dict(value,schema='affine-standalone-result-v1',status=status,distribution_sha256=digest(Path(__file__).read_bytes()),payload_sha256=PAYLOAD_SHA256,benchmark={'status':status})
    receipt_tools(payload).validate_envelope(full);receipt_tools(payload).validate_operator_probe(operator,required=required)


def envelope(payload,prepared,operator=None):
    return dict(schema='off-attribution-result-v2',status='prepare_only',diagnostic_valid=False,
        distribution_sha256=digest(Path(__file__).read_bytes()),payload_sha256=PAYLOAD_SHA256,
        primary_speed_claim=False,cpu_time_series_measured=False,
        production_source=production_receipt(payload,prepared['production_manifest'],operator),
        counter_source=prepared['source_proof'],counter_artifacts=prepared['artifact_receipts'],profile=None,counts=None,phase_identity_match=None)


def phase_match(profile,counts):
    if profile['status']!='complete' or counts['status']!='complete':return None
    a={r['initialization']['browser_instance_sha256'] for r in profile['sessions']}
    b={r['initialization']['browser_instance_sha256'] for r in counts['sessions']}
    a.add(profile['flag_acceptance']['browser_instance_sha256']);b.add(counts['flag_acceptance']['browser_instance_sha256'])
    return (same(profile['host'],counts['host']) and same(profile['environment']['engine'],counts['flag_acceptance']['engine'])
        and same(profile['output_reference'],counts['output_reference']) and not a.intersection(b)
        and all(s['initialization']['dispatch']['worker_hardware_concurrency']==profile['environment']['worker_hardware_concurrency'] for s in counts['sessions']))


def validate_envelope(payload,report):
    fields={'schema','status','diagnostic_valid','distribution_sha256','payload_sha256','primary_speed_claim','cpu_time_series_measured','production_source','counter_source','counter_artifacts','profile','counts','phase_identity_match'}
    need(type(report) is dict and set(report)==fields,'Attribution envelope schema')
    need(report['schema']=='off-attribution-result-v2' and report['status'] in {'complete','incomplete','prepare_only'},'Attribution status')
    need(report['distribution_sha256']==digest(Path(__file__).read_bytes()) and report['payload_sha256']==PAYLOAD_SHA256,'Distribution provenance')
    need(report['primary_speed_claim'] is False and report['cpu_time_series_measured'] is False,'Attribution is not a speed claim')
    need(report['diagnostic_valid'] is (report['status']=='complete'),'Validity differs from status')
    validate_production(payload,report['production_source'],required=report['status']!='prepare_only')
    import_helper(payload,'attribution_prepare').validate_public_proof(report['counter_source'],report['counter_artifacts'],payload)
    counter_wasm={r['wasm_sha256'] for r in report['counter_artifacts'].values()}
    production_wasm={r['wasm_sha256'] for r in report['production_source']['artifacts'].values()}
    need(len(counter_wasm)==2 and not counter_wasm.intersection(production_wasm),'Counter/production binary separation')
    profile,counts=report['profile'],report['counts']
    if report['status']=='prepare_only':
        need(profile is None and counts is None and report['phase_identity_match'] is None,'Prepare-only inference claim');return
    need(profile is not None,'Missing production profile phase')
    browser=import_helper(payload,'attribution_browser');browser.validate_report(profile)
    for key,row in profile['artifacts'].items():
        need(all(report['production_source']['artifacts'][key][x]==row[x] for x in ('js_sha256','wasm_sha256')),'Profile receipt mismatch')
    if counts is not None:
        need(profile['status']=='complete','Counter phase preceded valid profile phase')
        import_helper(payload,'counter_browser').validate_report(counts,browser.load_base(payload))
        for key,row in counts['artifacts'].items():
            need(all(report['counter_artifacts'][key][x]==row[x] for x in ('js_sha256','wasm_sha256')),'Counter receipt mismatch')
    expected=phase_match(profile,counts) if counts is not None else None
    need(report['phase_identity_match'] is expected,'Cross-phase evidence changed')
    need((report['status']=='complete') is (expected is True),'Combined validity mismatch')



def html_table(headers,rows):
    head=''.join('<th>'+html.escape(str(x))+'</th>' for x in headers)
    body=''.join('<tr>'+''.join('<td>'+html.escape(str(value))+'</td>' for value in row)+'</tr>' for row in rows)
    return '<div class="scroll"><table><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'


def hot_node_tables(profile):
    pieces=['<h2>Hot nodes by profiled duration</h2><p>Top 20 nodes per control, ranked by median duration across nine retained syntheses in three fresh sessions. Numeric shapes come from the first validated session for that control. Identity labels are SHA-256 prefixes. These descriptive node timings are not end-to-end latency or a speed ratio.</p>']
    for key in ('original','rebuilt','candidate'):
        summary=profile['summary']['conditions'][key]
        first=next(session for session in profile['sessions'] if session['condition']==key)
        structure={node['identity_sha256']:node for node in first['profile']['nodes']}
        hottest=sorted(summary['nodes'],key=lambda node:(-node['median_us'],node['identity_sha256']))[:20]
        rows=[]
        for node in hottest:
            shapes=structure[node['identity_sha256']]
            rows.append([node['identity_sha256'][:12],node['provider'],node['op'],
                json.dumps(shapes['input_shapes'],separators=(',',':')),json.dumps(shapes['output_shapes'],separators=(',',':')),
                format(node['median_us'],'.3f'),format(node['mean_us'],'.3f')])
        pieces.append('<h3>'+html.escape(key)+'</h3>'+html_table(['Identity hash','Provider','Op','Input shapes','Output shapes','Median (us)','Mean (us)'],rows))
    return ''.join(pieces)


def reshape_table(counts):
    original=next(session for session in counts['sessions'] if session['condition']=='original')
    records=original['counts']['reshape'];need(len(records)==38,'Expected complete reshape grid')
    rows=[]
    for row in records:
        rows.append([row['group_input_channels'],row['group_output_channels'],row['output_size'],
            str(row['kernel_height'])+'/'+str(row['kernel_width']),str(row['dilation_height'])+'/'+str(row['dilation_width']),
            row['mr'],row['nr'],row['nc'],row['num_threads'],row['task_type'],row['task_callback'],
            '/'.join(str(row['range'+str(i)]) for i in range(4)),str(row['tile0'])+'/'+str(row['tile1']),
            row['packed_weights_bytes'],row['reshape_count']])
    return '<h2>Actual reshape and task grid</h2><p>The original-source count session recorded 38 successful FP32 NHWC IGEMM signatures, including the NR2 row. Counts cover initialization plus warmups and counted inferences. Packed-weight bytes means groups multiplied by the actual gw_stride: the addressed packed-weight span. It excludes allocator padding and cache-tail alignment.</p>'+html_table(['Cin','Cout','M','Kh/Kw','Dh/Dw','MR','NR','NC','Threads','Task type','Callback','Ranges 0/1/2/3','Tiles 0/1','Packed-weight bytes','Count'],rows)

def resource_tables(payload,profile):
    browser=import_helper(payload,'attribution_browser')
    pieces=['<h2>Per-call resource windows</h2><p>Each production session has six separate execution windows: discarded warmups 0 and 1, retained syntheses 2, 3 and 4, and raw-output check 5. Major faults in warmup windows are disclosed and do not alone invalidate the diagnostic. Every other warmup resource guard remains strict. Retained and raw-output windows require zero major faults; all windows require unchanged swap, sufficient available memory, matched process counters and verified root identity. Resource observations never establish a speed claim.</p><p>Snapshots run outside native inference and ORT node-event timing intervals. These windows include controller bookkeeping, and intercall observation overhead may affect warmness. A completed execution does not mean its resource gate or output comparison passed. Only the final synthesis WAV and final raw output are checked for exactness, giving two checked outputs per complete session.</p>']
    if profile['summary'] is not None:
        rows=[]
        for role in ('warmup','retained_synthesis','raw_output_check'):
            row=profile['summary']['resource_observations'][role]
            rows.append([role,row['calls'],row['major_faults'],row['strict_resource_gate_failures'],
                'passed' if row['required_resource_gates_passed'] else 'failed','false'])
        pieces.append(html_table(['Role','Observed windows','Major faults','Strict-zero-fault gate failures','Required role gate','Speed attribution'],rows))
    for session in profile['sessions']:
        checks=2 if session['outputs'] is not None else 0
        pieces.append('<h3>Session '+str(session['index'])+' / '+html.escape(session['condition'])+'</h3><p>Completed executions: '+str(session['completed_inferences'])+' / 6. Exact checked outputs: '+str(checks)+' / 2.</p>')
        rows=[]
        for occurrence in range(6):
            if occurrence>=len(session['call_resources']):
                rows.append([occurrence,browser.call_role(occurrence),'not attempted',*(['not observed']*10)])
                continue
            call=session['call_resources'][occurrence];resource=call['resources']
            if resource is None:
                rows.append([occurrence,call['role'],'yes' if call['completed'] else 'no',*(['not observed']*10)])
                continue
            rows.append([occurrence,call['role'],'yes' if call['completed'] else 'no',resource['major_faults'],resource['minor_faults'],
                format(resource['cpu_seconds_delta'],'.6f'),str(resource['rss_bytes_before'])+'/'+str(resource['rss_bytes_after']),
                min(resource['before']['available_bytes'],resource['after']['available_bytes']),resource['target_swap_growth_bytes'],
                str(resource['host_swap_in_delta'])+'/'+str(resource['host_swap_out_delta']),
                str(resource['unmatched_processes'])+'/'+str(resource['counter_regressions']),
                'passed' if resource['passed'] else 'failed',
                'passed' if browser.call_resource_passed(resource,call['role']) else 'failed'])
        pieces.append(html_table(['Occurrence','Role','Execution complete','Major faults','Minor faults','CPU delta (s)','RSS before/after (bytes)',
            'Minimum available (bytes)','Target swap growth (bytes)','Host swap in/out (bytes)','Unmatched/regressed counters','Strict-zero-fault gate','Required role gate'],rows))
    return ''.join(pieces)


def render_html(payload,report):
    need(type(report) is dict,'Report type')
    if report.get('schema')==SCHEMA:minimal_validate(report)
    else:validate_envelope(payload,report)
    state={'complete':'Complete, validated diagnostic','incomplete':'Incomplete; no valid combined diagnostic','prepare_only':'Source preparation verified; no browser inference','failed':'Stopped; no valid diagnostic'}[report['status']]
    parts=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>VOICEVOX OFF attribution</title><style>body{font:16px system-ui;line-height:1.55;max-width:78rem;margin:3rem auto;padding:0 1.3rem;color:#172434;background:#f9fbfd}h1,h2{line-height:1.2}table{border-collapse:collapse;width:100%;margin:1rem 0}td,th{border-bottom:1px solid #ccd5df;text-align:left;padding:.5rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}details{border:1px solid #ccd5df;padding:1rem;border-radius:.5rem}.scroll{overflow:auto}td{vertical-align:top;white-space:nowrap}.note{background:#e9f0f8;padding:1rem;border-radius:.5rem}</style></head><body><h1>VOICEVOX OFF attribution</h1><p>'+html.escape(state)+'</p><p class="note">Diagnostic only. Profiled node durations are not end-to-end wall time or a primary speed claim. No optimization is promoted by this report.</p><p>Normal Chrome 153, revectorization OFF, strict FP32, fixture 962, XNNPACK 2 / ORT 1. Nine fresh production-profile sessions cover original, unchanged rebuilt and affine controls: a 54-inference budget with 27 retained syntheses. Two separate untimed counter sessions have an 8-inference budget. Raw profile events, node names, tensors, audio and models are excluded.</p>']
    profile,counts=report.get('profile'),report.get('counts')
    if profile:
        complete=sum(s['profile'] is not None for s in profile['sessions'])
        parts.append('<h2>Production profile phase</h2><p>Completed aggregate profiles: '+str(complete)+' / 9. Phase status: '+html.escape(profile['status'])+'.</p>')
        parts.append(resource_tables(payload,profile))
        if profile['summary']:
            parts.append('<table><thead><tr><th>Control</th><th>Retained syntheses</th><th>Nodes</th><th>Mean summed node duration per synthesis (ms)</th></tr></thead><tbody>')
            for key in ('original','rebuilt','candidate'):
                row=profile['summary']['conditions'][key]
                parts.append('<tr><td>'+html.escape(key)+'</td><td>'+str(row['retained_synthesis_calls'])+'</td><td>'+str(len(row['nodes']))+'</td><td>'+format(row['profiled_node_duration_sum_us']/row['retained_synthesis_calls']/1000,'.3f')+'</td></tr>')
            parts.append('</tbody></table><p>These are sums of per-node profiler durations, not browser elapsed latency. The rebuilt control exposes rebuild effects.</p>')
            parts.append(hot_node_tables(profile))
    if counts:
        parts.append('<h2>Separate count-only phase</h2><p>Status: '+html.escape(counts['status'])+'. Completed count records: '+str(sum(s['counts'] is not None for s in counts['sessions']))+' / 2. Timing is forbidden for these instrumented binaries.</p>')
        if counts['status']=='complete':
            parts.append('<p>Original and affine joint kernel multisets match after route aggregation; reshape metadata match exactly. Numeric records follow.</p>')
            parts.append(reshape_table(counts))
    parts.append('<details><summary>Complete validated aggregates and exact source receipts</summary><pre>'+html.escape(json.dumps(report,sort_keys=True,indent=2,allow_nan=False))+'</pre></details><p>Distribution SHA-256: '+html.escape(report['distribution_sha256'])+'</p></body></html>\n')
    return ''.join(parts)


def validate_output(output,payload):
    output=checked_path(output);need(output.is_dir() and {x.name for x in output.iterdir()}==PUBLIC_FILES,'Public output allowlist')
    for name in PUBLIC_FILES:
        path=checked_path(output/name);need(path.is_file() and path.stat().st_size<=16_000_000,'Public file type/bound')
    raw=(output/'summary.json').read_text();report=decode_json(raw)
    need(raw==json.dumps(report,sort_keys=True,indent=2,allow_nan=False)+'\n','Noncanonical public JSON')
    need((output/'report.html').read_text()==render_html(payload,report),'HTML differs from validated summary');return report


def save_public(output,payload,report):
    output=checked_path(output);need(output.is_dir(),'Missing public directory')
    need({x.name for x in output.iterdir()}<=PUBLIC_FILES,'Unexpected public file')
    rendered=render_html(payload,report);atomic_json(output/'summary.json',report)
    checked_path(output/'report.html').write_text(rendered);validate_output(output,payload)


def plan():
    return dict(schema=SCHEMA,embedded_files=len(load_payload()),payload_sha256=PAYLOAD_SHA256,fixture_frames=962,
        threads=dict(ort=1,xnnpack=2),seed=1729,production_conditions=['original','rebuilt','candidate'],
        fresh_production_sessions=9,production_inference_calls=54,retained_profiled_syntheses=27,
        resource_windows_per_production_session=6,exact_output_checks_per_production_session=2,
        warmup_major_faults='disclosed_not_a_speed_claim',retained_and_raw_major_faults_allowed=0,
        intercall_observation_may_affect_warmness=True,
        counter_sessions=2,counter_inference_calls=8,prepared_core_links=6,normal_tiering=True,revectorization='OFF',
        chromium_major=153,primary_speed_claim=False,cpu_time_series_measured=False,builds_performed=False,inference_performed=False,downloads_performed=False)


def self_test(payload):
    sys.modules['_off_distribution']=sys.modules[__name__];sys.path.insert(0,str(payload));sys.path.insert(0,str(payload/'source'))
    # Preserve the old affine wrapper test source for provenance, but it tests
    # that different entrypoint and must not be imported as this distribution.
    names=[path.stem for path in sorted(Path(payload).glob('test_*.py')) if path.name!='test_affine_wrapper.py']
    suite=unittest.TestSuite(unittest.defaultTestLoader.loadTestsFromName(name) for name in names)
    need(suite.countTestCases()>=60,'Embedded tests absent')
    with io.StringIO() as buffer:
        result=unittest.TextTestRunner(stream=buffer,verbosity=1).run(suite)
        if not result.wasSuccessful():print(buffer.getvalue(),file=sys.stderr);raise RuntimeError('Offline tests failed')
    try:
        import playwright
        node=Path(playwright.__file__).parent/'driver/node'
    except ImportError:node=Path(shutil.which('node') or '')
    need(node.is_file(),'Node required for offline JavaScript tests')
    for name in ('test_profile_reduce.js','test_counter_browser.js'):
        subprocess.run([str(node),'--test',str(payload/name)],check=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    return dict(python_tests=result.testsRun,javascript_suites=2,skipped=len(result.skipped),passed=True,inference_calls=0,core_builds=0,native_unit_compilations=2)



def disk_preflight(cache,stage):
    need(stage in STAGES,'Unknown disk-check stage')
    minimum=LINK_DISK_MINIMUM if stage.startswith(('link_','attribution_link_')) else BUILD_DISK_MINIMUM if stage in {'toolchains','pinned_inputs','forced_dispatch','activation_sources','affine_sources','attribution_sources','browser_install'} else 0
    if minimum:need(shutil.disk_usage(cache).free>=minimum,'Insufficient private-cache disk space')

def worker(args):
    payload=extract_payload(args.payload);private=Path(args.private);progress=Path(args.progress)
    def stage(value):
        need(value in STAGES,'Unknown stage');disk_preflight(Path(args.cache),value);atomic_json(progress,{'stage':value})
    stage('payload_verified')
    with (Path(args.cache)/'off-attribution-run.lock').open('w') as lock:
        import fcntl
        fcntl.flock(lock.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
        prepared=import_helper(payload,'attribution_prepare').prepare(payload,Path(args.cache),stage,args.sdk_path)
        atomic_json(private/'prepared-manifest.json',prepared)
        if args.prepare_only:
            result=envelope(payload,prepared);validate_envelope(payload,result)
        else:
            stage('operator_gate');operator=import_helper(payload,'affine_prepare').run_operator_probe(prepared['production_manifest'],private)
            receipt_tools(payload).validate_operator_probe(operator,required=True);atomic_json(private/'operator-receipt.json',operator)
            stage('browser_install');subprocess.run([sys.executable,'-m','playwright','install','chromium'],check=True)
            result=envelope(payload,prepared,operator);result['status']='incomplete';stage('profile_sessions')
            with tempfile.TemporaryDirectory(prefix='profile-assets-',dir=private) as assets:
                result['profile']=import_helper(payload,'attribution_browser').run(prepared['production_manifest'],payload,Path(assets))
            atomic_json(private/'aggregate-checkpoint.json',result)
            if result['profile']['status']=='complete':
                stage('counter_sessions')
                with tempfile.TemporaryDirectory(prefix='counter-assets-',dir=private) as assets:
                    result['counts']=import_helper(payload,'counter_browser').run(prepared['counter_manifest'],payload,Path(assets))
                result['phase_identity_match']=phase_match(result['profile'],result['counts'])
                if result['phase_identity_match'] is True:result.update(status='complete',diagnostic_valid=True)
            validate_envelope(payload,result)
        atomic_json(Path(args.result),result);stage('complete')


def safe_exception(error):return type(error).__name__ if type(error).__name__ in ERRORS else 'OtherError'


def parser():
    p=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('--cache-dir',type=Path,default=Path(os.environ.get('XDG_CACHE_HOME',Path.home()/'.cache'))/'voicevox-off-attribution',help='Private cache; never upload')
    p.add_argument('--sdk-path',type=Path,help='Optional exact SDK 4.0.8; source/compiler/IR pins remain mandatory')
    p.add_argument('--output',type=Path,default=Path('off-attribution-report'),help='New/empty public directory for summary.json and report.html')
    p.add_argument('--prepare-only',action='store_true',help='Prepare six CORE links/source gates; no browser inference')
    p.add_argument('--dry-run',action='store_true',help='Verify embedded source and show bounded plan without downloads/builds/inference')
    p.add_argument('--self-test',action='store_true',help='Run embedded offline source, lifecycle, privacy/report tests')
    p.add_argument('--validate-report',type=Path,help='Validate canonical summary and exact regenerated HTML')
    p.add_argument('--extract-helpers',type=Path,help='Extract verified source without building/inferring')
    p.add_argument('--_worker',action='store_true',help=argparse.SUPPRESS)
    for key in ('payload','progress','private','result','cache'):p.add_argument('--_'+key,dest=key,help=argparse.SUPPRESS)
    return p


def main(argv=None):
    args=parser().parse_args(argv)
    if args._worker:return worker(args)
    need(sum(bool(x) for x in (args.prepare_only,args.dry_run,args.self_test,args.validate_report,args.extract_helpers))<=1,'Choose one mode')
    if args.extract_helpers:
        extract_payload(args.extract_helpers);print('OFF_ATTRIBUTION_SOURCE '+json.dumps({'files':len(load_payload()),'verified':True},sort_keys=True));return 0
    with tempfile.TemporaryDirectory(prefix='off-attribution-embedded-') as temp:
        payload=extract_payload(Path(temp))
        if args.self_test:print('OFF_ATTRIBUTION_SELF_TEST '+json.dumps(self_test(payload),sort_keys=True));return 0
        if args.validate_report:
            report=validate_output(args.validate_report,payload);print('OFF_ATTRIBUTION_VALIDATED '+json.dumps({'valid':True,'status':report['status'],'files':sorted(PUBLIC_FILES)},sort_keys=True));return 0
        if args.dry_run:print('OFF_ATTRIBUTION_PLAN '+json.dumps(plan(),sort_keys=True));return 0
    cache=checked_path(args.cache_dir);output=checked_path(args.output)
    need(not output.is_relative_to(cache) and not cache.is_relative_to(output),'Public/private directories overlap')
    need(not output.exists() or output.is_dir() and not any(output.iterdir()),'Refuse overwrite of public output')
    os.umask(0o077);cache.mkdir(parents=True,exist_ok=True,mode=0o700);cache.chmod(0o700);output.mkdir(parents=True,exist_ok=True,mode=0o700)
    payload=extract_payload(cache/('embedded-'+PAYLOAD_SHA256[:16]));private=Path(tempfile.mkdtemp(prefix='run-',dir=cache))
    progress=private/'progress.json';result=private/'result.json';log=private/'private.log'
    env=dict(os.environ);env.pop('PYTHONOPTIMIZE',None);env['PYTHONUNBUFFERED']='1';env['PLAYWRIGHT_BROWSERS_PATH']=str(cache/'playwright')
    command=[sys.executable,str(Path(__file__).resolve()),'--_worker','--_payload',str(payload),'--_progress',str(progress),'--_private',str(private),'--_result',str(result),'--_cache',str(cache)]
    if args.prepare_only:command+=['--prepare-only']
    if args.sdk_path:command+=['--sdk-path',str(checked_path(args.sdk_path))]
    stage='initializing';child=None
    try:
        with log.open('wb') as stream:
            child=subprocess.Popen(command,stdout=stream,stderr=subprocess.STDOUT,env=env,start_new_session=True)
            while child.poll() is None:
                if progress.exists():
                    item=decode_json(progress.read_text());need(set(item)=={'stage'} and item['stage'] in STAGES,'Private stage schema')
                    if item['stage']!=stage:stage=item['stage'];print('OFF_ATTRIBUTION_STAGE '+json.dumps({'stage':stage},sort_keys=True),flush=True)
                time.sleep(2)
            need(child.returncode==0 and result.is_file(),'Worker did not complete')
        report=decode_json(result.read_text());save_public(output,payload,report)
        print('OFF_ATTRIBUTION_FINISHED '+json.dumps({'status':report['status'],'validated_public_files':sorted(PUBLIC_FILES)},sort_keys=True))
        return 0 if report['status'] in {'complete','prepare_only'} else 1
    except BaseException as error:
        if child is not None and child.poll() is None:
            import signal
            os.killpg(child.pid,signal.SIGTERM)
            try:child.wait(timeout=15)
            except subprocess.TimeoutExpired:os.killpg(child.pid,signal.SIGKILL);child.wait()
        report=minimal_report('failed',stage,safe_exception(error));checkpoint=private/'aggregate-checkpoint.json'
        if checkpoint.is_file():
            try:
                candidate=decode_json(checkpoint.read_text());validate_envelope(payload,candidate);report=candidate
            except Exception:pass
        save_public(output,payload,report)
        print('OFF_ATTRIBUTION_FAILED '+json.dumps({'stage':stage,'exception_class':safe_exception(error)},sort_keys=True),file=sys.stderr);return 1


